        if !turn.isForeground { return .background }
        switch turn.task {
        case .backgroundTrigger:
            return .background
        case .agentPlan, .toolDecision, .speechCommandParsing:
            return .tool
        case .summarization, .memoryExtraction, .remConsolidation:
            return .memory
