    private let lock = NSLock()
    private var cancelledReason: String?

    func cancel(reason: String) {
        lock.lock()
        if cancelledReason == nil {
            cancelledReason = reason
        }
        lock.unlock()
    }

    var isCancelled: Bool {
        lock.lock()
        defer { lock.unlock() }
        return cancelledReason != nil
    }

    var reason: String? {
        lock.lock()
        defer { lock.unlock() }
        return cancelledReason
    }
